/// <summary>
/// PricingAttribute of table <c>CustTable</c> field CustClassificationId.
/// </summary>
[GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::Customer, GUPPricingAttributeSourceLevel::Header)]
[GUPPricingAttributeFieldsDiscovery(fieldStr(CustTable, CustClassificationId))]
internal class GUPPricingAttributeCustTableCustClassificationId extends GUPPricingAttributeCustTable implements GUPIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(CustTable, CustClassificationId);
}

public Set getAllowedValuesWithDescription()
{
    var ret = new Set(Types::AnyType);

    CustTable               custTable;
    CustClassificationGroup custClassificationGroup;

    while select CustClassificationId from custtable
        group by CustClassificationId
        join custClassificationGroup
        group by Code, Txt
        where custTable.CustClassificationId == custClassificationGroup.Code
    {
        GUPPricingAttributeAllowedValuesObject valueObject =
            new GUPPricingAttributeAllowedValuesObject(custClassificationGroup.Code, custClassificationGroup.Txt);
        ret.add(valueObject);
    }
    return ret;
}
